#!/system/bin/sh
# One HTTP request is handled by one mksh process launched by toybox nc -L.
# Model binaries and Qualcomm libraries are external assets; this file contains
# only fixed command lines and protocol handling.

umask 077
set -f
export LC_ALL=C

SCRIPT_DIR=${0%/*}
if [ "$SCRIPT_DIR" = "$0" ]; then
  SCRIPT_DIR=.
fi
if [ -f "$SCRIPT_DIR/env.sh" ]; then
  # env.sh is generated by deploy.sh from validated, fixed remote paths.
  # shellcheck disable=SC1091
  . "$SCRIPT_DIR/env.sh"
fi

ASR_COMPANION_ROOT=${ASR_COMPANION_ROOT:-/data/local/tmp/lmf-asr-companion}
ASR_RUNNER_ROOT=${ASR_RUNNER_ROOT:-$ASR_COMPANION_ROOT/bin}
QNN_RUNTIME_ROOT=${QNN_RUNTIME_ROOT:-$ASR_COMPANION_ROOT/qnn-runtime}
SENSEVOICE_MODEL_ROOT=${SENSEVOICE_MODEL_ROOT:-$ASR_COMPANION_ROOT/models/sensevoice}
RUSSIAN_MODEL_ROOT=${RUSSIAN_MODEL_ROOT:-$ASR_COMPANION_ROOT/models/russian}
ASR_TMP_ROOT=${ASR_TMP_ROOT:-$ASR_COMPANION_ROOT/tmp}
ASR_RUNNER=${ASR_RUNNER:-$ASR_RUNNER_ROOT/sherpa-onnx-offline}

HARD_MAX_WAV_BYTES=320044
MIN_WAV_BYTES=46
MAX_WAV_BYTES=$HARD_MAX_WAV_BYTES
case "${ASR_MAX_WAV_BYTES:-}" in
  ''|*[!0-9]*) ;;
  *)
    if [ "$ASR_MAX_WAV_BYTES" -ge "$MIN_WAV_BYTES" ] && \
       [ "$ASR_MAX_WAV_BYTES" -le "$HARD_MAX_WAV_BYTES" ]; then
      MAX_WAV_BYTES=$ASR_MAX_WAV_BYTES
    fi
    ;;
esac

case "${ASR_CPU_THREADS:-2}" in
  1|2|3|4) CPU_THREADS=$ASR_CPU_THREADS ;;
  *) CPU_THREADS=2 ;;
esac

toybox mkdir -p "$ASR_TMP_ROOT" 2>/dev/null
request_dir=
attempt=0
while [ "$attempt" -lt 8 ]; do
  candidate_dir="$ASR_TMP_ROOT/request.$$.$RANDOM.$attempt"
  if toybox mkdir "$candidate_dir" 2>/dev/null; then
    request_dir=$candidate_dir
    break
  fi
  attempt=$((attempt + 1))
done
if [ -z "$request_dir" ]; then
  printf 'HTTP/1.1 500 Internal Server Error\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: 72\r\nConnection: close\r\n\r\n{"ok":false,"error":{"code":"temp_unavailable","message":"No temp dir"}}'
  exit 1
fi

cleanup() {
  if [ -n "$request_dir" ] && [ -d "$request_dir" ]; then
    toybox rm -rf "$request_dir"
  fi
}
trap cleanup 0 1 2 15

cors_headers() {
  printf 'Access-Control-Allow-Origin: *\r\n'
  printf 'Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n'
  printf 'Access-Control-Allow-Headers: Content-Type, Content-Length\r\n'
  printf 'Access-Control-Allow-Private-Network: true\r\n'
  printf 'Access-Control-Max-Age: 600\r\n'
}

respond_file() {
  typeset status_code=$1
  typeset status_text=$2
  typeset body_file=$3
  typeset body_bytes
  body_bytes=$(toybox wc -c < "$body_file" | toybox tr -d ' \t\r\n')
  printf 'HTTP/1.1 %s %s\r\n' "$status_code" "$status_text"
  printf 'Content-Type: application/json; charset=utf-8\r\n'
  printf 'Content-Length: %s\r\n' "$body_bytes"
  printf 'Cache-Control: no-store\r\n'
  cors_headers
  printf 'Connection: close\r\n\r\n'
  toybox cat "$body_file"
}

respond_error() {
  typeset status_code=$1
  typeset status_text=$2
  typeset error_code=$3
  typeset error_message=$4
  typeset body_file="$request_dir/error.json"
  # All callers pass fixed ASCII literals, never request data.
  printf '{"ok":false,"error":{"code":"%s","message":"%s"}}' \
    "$error_code" "$error_message" > "$body_file"
  respond_file "$status_code" "$status_text" "$body_file"
}

backend_ready_qnn() {
  [ -x "$ASR_RUNNER" ] && \
  [ -f "$ASR_RUNNER_ROOT/libonnxruntime.so" ] && \
  [ -f "$QNN_RUNTIME_ROOT/libQnnHtp.so" ] && \
  [ -f "$QNN_RUNTIME_ROOT/libQnnSystem.so" ] && \
  [ -f "$QNN_RUNTIME_ROOT/libQnnHtpV81Stub.so" ] && \
  [ -f "$QNN_RUNTIME_ROOT/libQnnHtpV81Skel.so" ] && \
  [ -f "$SENSEVOICE_MODEL_ROOT/model.bin" ] && \
  [ -f "$SENSEVOICE_MODEL_ROOT/tokens.txt" ]
}

backend_ready_ru() {
  [ -x "$ASR_RUNNER" ] && \
  [ -f "$ASR_RUNNER_ROOT/libonnxruntime.so" ] && \
  [ -f "$RUSSIAN_MODEL_ROOT/encoder.int8.onnx" ] && \
  [ -f "$RUSSIAN_MODEL_ROOT/decoder.onnx" ] && \
  [ -f "$RUSSIAN_MODEL_ROOT/joiner.int8.onnx" ] && \
  [ -f "$RUSSIAN_MODEL_ROOT/tokens.txt" ]
}

write_health() {
  typeset qnn_ready=false
  typeset ru_ready=false
  typeset all_ready=false
  backend_ready_qnn && qnn_ready=true
  backend_ready_ru && ru_ready=true
  if [ "$qnn_ready" = true ] && [ "$ru_ready" = true ]; then
    all_ready=true
  fi
  printf '{"ok":%s,"service":"lmf-android-asr-companion","schema_version":1,"listen":"127.0.0.1:6010","input":{"format":"pcm_s16le_wav","sample_rate_hz":16000,"channels":1,"max_audio_seconds":10,"max_content_length":%s},"backends":{"sensevoice_qnn":{"ready":%s,"languages":["zh","en","auto","qnn-auto"]},"zipformer_ru_cpu":{"ready":%s,"languages":["ru","auto"]}}}' \
    "$all_ready" "$MAX_WAV_BYTES" "$qnn_ready" "$ru_ready" > "$request_dir/health.json"
  if [ "$all_ready" = true ]; then
    respond_file 200 OK "$request_dir/health.json"
  else
    respond_file 503 "Service Unavailable" "$request_dir/health.json"
  fi
}

ascii_at() {
  toybox dd if="$wav_file" bs=1 skip="$1" count="$2" 2>/dev/null
}

u16_at() {
  toybox od -An -tu2 -j "$1" -N 2 "$wav_file" 2>/dev/null | toybox tr -d ' \t\r\n'
}

u32_at() {
  toybox od -An -tu4 -j "$1" -N 4 "$wav_file" 2>/dev/null | toybox tr -d ' \t\r\n'
}

validate_wav() {
  typeset riff wave fmt data
  typeset riff_size fmt_size audio_format channels sample_rate byte_rate
  typeset block_align bits_per_sample data_size expected_data expected_riff

  riff=$(ascii_at 0 4)
  wave=$(ascii_at 8 4)
  fmt=$(ascii_at 12 4)
  data=$(ascii_at 36 4)
  [ "$riff" = RIFF ] || return 1
  [ "$wave" = WAVE ] || return 1
  [ "$fmt" = "fmt " ] || return 1
  [ "$data" = data ] || return 1

  riff_size=$(u32_at 4)
  fmt_size=$(u32_at 16)
  audio_format=$(u16_at 20)
  channels=$(u16_at 22)
  sample_rate=$(u32_at 24)
  byte_rate=$(u32_at 28)
  block_align=$(u16_at 32)
  bits_per_sample=$(u16_at 34)
  data_size=$(u32_at 40)
  case "$riff_size:$fmt_size:$audio_format:$channels:$sample_rate:$byte_rate:$block_align:$bits_per_sample:$data_size" in
    *[!0-9:]*|:*|*:|*::*) return 1 ;;
  esac
  expected_data=$((content_length - 44))
  expected_riff=$((content_length - 8))
  [ "$riff_size" -eq "$expected_riff" ] || return 1
  [ "$fmt_size" -eq 16 ] || return 1
  [ "$audio_format" -eq 1 ] || return 1
  [ "$channels" -eq 1 ] || return 1
  [ "$sample_rate" -eq 16000 ] || return 1
  [ "$byte_rate" -eq 32000 ] || return 1
  [ "$block_align" -eq 2 ] || return 1
  [ "$bits_per_sample" -eq 16 ] || return 1
  [ "$data_size" -eq "$expected_data" ] || return 1
  [ $((data_size % 2)) -eq 0 ] || return 1
  return 0
}

json_result_valid() {
  typeset result_file=$1
  typeset first last
  [ -s "$result_file" ] || return 1
  first=$(toybox head -c 1 "$result_file")
  last=$(toybox tr -d ' \t\r\n' < "$result_file" | toybox tail -c 1)
  [ "$first" = "{" ] || return 1
  [ "$last" = "}" ] || return 1
  toybox grep -q '"text"' "$result_file" || return 1
  return 0
}

run_qnn() {
  typeset language=$1
  typeset result_file=$2
  typeset log_file=$3
  typeset status raw_output
  case "$language" in
    zh|en|auto) ;;
    *) return 2 ;;
  esac
  backend_ready_qnn || return 3
  raw_output="$result_file.raw"
  LD_LIBRARY_PATH="$ASR_RUNNER_ROOT:$QNN_RUNTIME_ROOT" \
  ADSP_LIBRARY_PATH="$QNN_RUNTIME_ROOT;${ADSP_LIBRARY_PATH:-}" \
  "$ASR_RUNNER" \
    --provider=qnn \
    --tokens="$SENSEVOICE_MODEL_ROOT/tokens.txt" \
    --sense-voice-language="$language" \
    --sense-voice-use-itn=true \
    --sense-voice.qnn-backend-lib="$QNN_RUNTIME_ROOT/libQnnHtp.so" \
    --sense-voice.qnn-system-lib="$QNN_RUNTIME_ROOT/libQnnSystem.so" \
    --sense-voice.qnn-context-binary="$SENSEVOICE_MODEL_ROOT/model.bin" \
    "$wav_file" > "$raw_output" 2> "$log_file"
  status=$?
  toybox grep '^{' "$raw_output" 2>/dev/null | toybox tail -n 1 > "$result_file"
  if [ "$status" -ne 0 ] || ! json_result_valid "$result_file"; then
    printf 'SenseVoice QNN failed (status %s)\n' "$status" >&2
    toybox tail -n 20 "$log_file" >&2 2>/dev/null
    return 4
  fi
  return 0
}

run_ru() {
  typeset result_file=$1
  typeset log_file=$2
  typeset status raw_output
  backend_ready_ru || return 3
  raw_output="$result_file.raw"
  LD_LIBRARY_PATH="$ASR_RUNNER_ROOT:$QNN_RUNTIME_ROOT" \
  "$ASR_RUNNER" \
    --provider=cpu \
    --tokens="$RUSSIAN_MODEL_ROOT/tokens.txt" \
    --encoder="$RUSSIAN_MODEL_ROOT/encoder.int8.onnx" \
    --decoder="$RUSSIAN_MODEL_ROOT/decoder.onnx" \
    --joiner="$RUSSIAN_MODEL_ROOT/joiner.int8.onnx" \
    --num-threads="$CPU_THREADS" \
    --decoding-method=greedy_search \
    "$wav_file" "$wav_file" > "$raw_output" 2> "$log_file"
  status=$?
  toybox grep '^{' "$raw_output" 2>/dev/null | toybox tail -n 1 > "$result_file"
  if [ "$status" -ne 0 ] || ! json_result_valid "$result_file"; then
    printf 'Russian Zipformer CPU failed (status %s)\n' "$status" >&2
    toybox tail -n 20 "$log_file" >&2 2>/dev/null
    return 4
  fi
  return 0
}

write_candidate() {
  typeset output_file=$1
  typeset backend=$2
  typeset provider=$3
  typeset status=$4
  typeset result_file=$5
  if [ "$status" -eq 0 ]; then
    printf '{"backend":"%s","provider":"%s","ok":true,"result":' "$backend" "$provider" >> "$output_file"
    toybox cat "$result_file" >> "$output_file"
    printf '}' >> "$output_file"
  else
    printf '{"backend":"%s","provider":"%s","ok":false,"error":{"code":"backend_failed","message":"ASR backend failed; inspect service log"}}' \
      "$backend" "$provider" >> "$output_file"
  fi
}

run_explicit() {
  typeset language=$1
  typeset result_file="$request_dir/result.json"
  typeset log_file="$request_dir/runner.log"
  typeset body_file="$request_dir/response.json"
  typeset status backend provider
  if [ "$language" = ru ]; then
    backend=zipformer_ru_cpu
    provider=cpu
    run_ru "$result_file" "$log_file"
    status=$?
  else
    backend=sensevoice_qnn
    provider=qnn
    if [ "$language" = qnn-auto ]; then
      run_qnn auto "$result_file" "$log_file"
    else
      run_qnn "$language" "$result_file" "$log_file"
    fi
    status=$?
  fi
  printf '{"ok":' > "$body_file"
  if [ "$status" -eq 0 ]; then
    printf 'true' >> "$body_file"
  else
    printf 'false' >> "$body_file"
  fi
  printf ',"schema_version":1,"requested_language":"%s","candidates":[' "$language" >> "$body_file"
  write_candidate "$body_file" "$backend" "$provider" "$status" "$result_file"
  printf ']}' >> "$body_file"
  if [ "$status" -eq 0 ]; then
    respond_file 200 OK "$body_file"
  else
    respond_file 503 "Service Unavailable" "$body_file"
  fi
}

run_auto() {
  typeset qnn_result="$request_dir/qnn-result.json"
  typeset qnn_log="$request_dir/qnn.log"
  typeset ru_result="$request_dir/ru-result.json"
  typeset ru_log="$request_dir/ru.log"
  typeset body_file="$request_dir/response.json"
  typeset qnn_pid ru_pid qnn_status ru_status top_ok complete

  run_qnn auto "$qnn_result" "$qnn_log" &
  qnn_pid=$!
  run_ru "$ru_result" "$ru_log" &
  ru_pid=$!
  wait "$qnn_pid"
  qnn_status=$?
  wait "$ru_pid"
  ru_status=$?

  top_ok=false
  complete=false
  if [ "$qnn_status" -eq 0 ] || [ "$ru_status" -eq 0 ]; then
    top_ok=true
  fi
  if [ "$qnn_status" -eq 0 ] && [ "$ru_status" -eq 0 ]; then
    complete=true
  fi
  printf '{"ok":%s,"complete":%s,"schema_version":1,"requested_language":"auto","selection_required":true,"candidates":[' \
    "$top_ok" "$complete" > "$body_file"
  write_candidate "$body_file" sensevoice_qnn qnn "$qnn_status" "$qnn_result"
  printf ',' >> "$body_file"
  write_candidate "$body_file" zipformer_ru_cpu cpu "$ru_status" "$ru_result"
  printf ']}' >> "$body_file"
  if [ "$top_ok" = true ]; then
    respond_file 200 OK "$body_file"
  else
    respond_file 503 "Service Unavailable" "$body_file"
  fi
}

cr=$(printf '\r')
if ! IFS= read -r request_line; then
  respond_error 400 "Bad Request" bad_request "Missing request line"
  exit 0
fi
request_line=${request_line%"$cr"}
# Word splitting is intentional for the three HTTP request-line fields; globbing
# is disabled at process start.
# shellcheck disable=SC2086
set -- $request_line
if [ "$#" -ne 3 ]; then
  respond_error 400 "Bad Request" bad_request "Malformed request line"
  exit 0
fi
request_method=$1
request_target=$2
http_version=$3
case "$http_version" in
  HTTP/1.0|HTTP/1.1) ;;
  *)
    respond_error 505 "HTTP Version Not Supported" http_version "Use HTTP/1.0 or HTTP/1.1"
    exit 0
    ;;
esac

content_length=
content_type=
transfer_encoding=
header_count=0
while IFS= read -r header_line; do
  header_line=${header_line%"$cr"}
  [ -z "$header_line" ] && break
  header_count=$((header_count + 1))
  if [ "$header_count" -gt 64 ]; then
    respond_error 431 "Request Header Fields Too Large" headers_too_large "Too many headers"
    exit 0
  fi
  case "$header_line" in
    *:*) ;;
    *)
      respond_error 400 "Bad Request" bad_header "Malformed header"
      exit 0
      ;;
  esac
  header_name=${header_line%%:*}
  header_value=${header_line#*:}
  while [ "${header_value# }" != "$header_value" ]; do header_value=${header_value# }; done
  header_name=$(printf '%s' "$header_name" | toybox tr '[:upper:]' '[:lower:]')
  case "$header_name" in
    content-length)
      if [ -n "$content_length" ]; then
        respond_error 400 "Bad Request" duplicate_content_length "Duplicate Content-Length"
        exit 0
      fi
      content_length=$header_value
      ;;
    content-type) content_type=$header_value ;;
    transfer-encoding) transfer_encoding=$header_value ;;
  esac
done

if [ "$request_method" = GET ] && [ "$request_target" = /health ]; then
  write_health
  exit 0
fi

if [ "$request_method" = OPTIONS ]; then
  case "$request_target" in
    /asr|/asr\?*)
      : > "$request_dir/options.json"
      respond_file 204 "No Content" "$request_dir/options.json"
      exit 0
      ;;
  esac
fi

if [ "$request_method" != POST ]; then
  respond_error 405 "Method Not Allowed" method_not_allowed "Use GET /health or POST /asr"
  exit 0
fi

case "$request_target" in
  /asr\?language=zh) requested_language=zh ;;
  /asr\?language=en) requested_language=en ;;
  /asr\?language=ru) requested_language=ru ;;
  /asr\?language=auto) requested_language=auto ;;
  /asr\?language=qnn-auto) requested_language=qnn-auto ;;
  *)
    respond_error 404 "Not Found" route_not_found "Expected /asr?language=zh|en|ru|auto|qnn-auto"
    exit 0
    ;;
esac

if [ -n "$transfer_encoding" ]; then
  respond_error 400 "Bad Request" transfer_encoding "Transfer-Encoding is not accepted"
  exit 0
fi
case "$content_length" in
  ''|*[!0-9]*)
    respond_error 411 "Length Required" content_length "A decimal Content-Length is required"
    exit 0
    ;;
  0*)
    respond_error 400 "Bad Request" content_length "Content-Length must not have leading zeroes"
    exit 0
    ;;
esac
if [ "${#content_length}" -gt 6 ]; then
  respond_error 413 "Payload Too Large" body_too_large "Maximum audio duration is 10 seconds"
  exit 0
fi
if [ "$content_length" -lt "$MIN_WAV_BYTES" ]; then
  respond_error 400 "Bad Request" body_too_small "WAV body is too small"
  exit 0
fi
if [ "$content_length" -gt "$MAX_WAV_BYTES" ]; then
  respond_error 413 "Payload Too Large" body_too_large "Maximum audio duration is 10 seconds"
  exit 0
fi

content_type=$(printf '%s' "$content_type" | toybox tr '[:upper:]' '[:lower:]')
case "$content_type" in
  audio/wav|audio/x-wav|application/octet-stream) ;;
  *)
    respond_error 415 "Unsupported Media Type" content_type "Use audio/wav with PCM16 mono 16 kHz"
    exit 0
    ;;
esac

wav_file="$request_dir/input.wav"
toybox head -c "$content_length" > "$wav_file"
received_bytes=$(toybox wc -c < "$wav_file" | toybox tr -d ' \t\r\n')
if [ "$received_bytes" -ne "$content_length" ]; then
  respond_error 400 "Bad Request" incomplete_body "Body is shorter than Content-Length"
  exit 0
fi
if ! validate_wav; then
  respond_error 422 "Unprocessable Content" invalid_wav "Expected canonical 16 kHz mono PCM16 WAV"
  exit 0
fi

if [ "$requested_language" = auto ]; then
  run_auto
else
  run_explicit "$requested_language"
fi
exit 0
